const ENDFEEL = ['Normal','Firm/capsular','Hard (bony)','Soft (tissue approx.)','Springy block','Empty (pain)','Spasm'];
const PAINROM = ['No pain','Pain at end range','Pain through range','Painful arc','Reproduces referred pain'];
const LIMIT = ['Full','Minimal loss','Moderate loss','Major loss','Nil'];
const MOB = ['Normal','Hypomobile','Hypermobile'];
const PAINRESP = ['None','Local pain','Comparable (reproduces)','Referred'];
const TENDER = ['0 None','1 Mild','2 Winces','3 Withdraws','4 Untouchable'];
const TONE = ['Normal','Increased/spasm','Decreased','Trigger points','Swelling','Warmth','Crepitus'];
const GRADE4 = ['None','Mild','Moderate','Severe'];
const TEAR = ['Normal','Tendinosis','Partial tear','Full-thickness tear','Complete rupture','Calcification','Tenosynovitis','Post-op / repaired'];
