const CART = ['Normal','ICRS 1','ICRS 2','ICRS 3','ICRS 4','Osteochondral lesion'];
const BONE = ['Normal','Bone marrow oedema','Bone bruise','Stress reaction','Fracture','AVN','Cyst','Osteophytes'];
const LUMBAR_LEVELS = ['T12–L1','L1–L2','L2–L3','L3–L4','L4–L5','L5–S1'];
const CERV_LEVELS = ['C2–C3','C3–C4','C4–C5','C5–C6','C6–C7','C7–T1'];

