const romLR = (k, rows) => ({tbl:{k, cols:[{h:'L active°',t:'num'},{h:'L passive°',t:'num'},{h:'R active°',t:'num'},{h:'R passive°',t:'num'},{h:'End feel',t:'sel',o:ENDFEEL},{h:'Pain / comments'}], rows}});
const spineROM = (k, rows) => ({tbl:{k, cols:[{h:'AROM (°)',t:'num'},{h:'PROM / OP',ph:'° or response'},{h:'Limitation',t:'sel',o:LIMIT},{h:'Pain',t:'sel',o:PAINROM},{h:'End feel',t:'sel',o:ENDFEEL},{h:'Deviation / quality'}], rows}});
