const lenLR = (k, rows) => ({tbl:{k, cols:[{h:'Left'},{h:'Right'},{h:'Comments'}], rows}});
const palpLR = (k, rows) => ({tbl:{k, cols:[{h:'L tenderness',t:'sel',o:TENDER},{h:'R tenderness',t:'sel',o:TENDER},{h:'Tone / tissue',t:'sel',o:TONE},{h:'Comments'}], rows}});
const mriStruct = (k, rows, def) => ({tbl:{k, cols:[{h:'Finding',t:'sel',o:def,rowOpts:1},{h:'Grade / size'},{h:'Comments'}], rows}});
