const SIX = (a) => a;
const QDEF = {
  odi:{t:'Oswestry Disability Index (ODI v2.1a)', short:'ODI', items:[
    ['1. Pain intensity',['I have no pain at the moment','The pain is very mild at the moment','The pain is moderate at the moment','The pain is fairly severe at the moment','The pain is very severe at the moment','The pain is the worst imaginable at the moment']],
    ['2. Personal care (washing, dressing)',['I can look after myself normally without causing extra pain','I can look after myself normally but it causes extra pain','It is painful to look after myself and I am slow and careful','I need some help but manage most of my personal care','I need help every day in most aspects of self-care','I do not get dressed, wash with difficulty and stay in bed']],
    ['3. Lifting',['I can lift heavy weights without extra pain','I can lift heavy weights but it gives extra pain','Pain prevents lifting heavy weights off the floor, but I manage if conveniently placed (e.g. on a table)','Pain prevents lifting heavy weights, but I manage light–medium weights if conveniently positioned','I can lift very light weights','I cannot lift or carry anything at all']],
    ['4. Walking',['Pain does not prevent me walking any distance','Pain prevents me walking more than 1 mile (1.6 km)','Pain prevents me walking more than ½ mile (800 m)','Pain prevents me walking more than 100 yards (100 m)','I can only walk using a stick or crutches','I am in bed most of the time']],
    ['5. Sitting',['I can sit in any chair as long as I like','I can only sit in my favourite chair as long as I like','Pain prevents me sitting more than 1 hour','Pain prevents me sitting more than 30 minutes','Pain prevents me sitting more than 10 minutes','Pain prevents me from sitting at all']],
    ['6. Standing',['I can stand as long as I want without extra pain','I can stand as long as I want but it gives extra pain','Pain prevents me standing for more than 1 hour','Pain prevents me standing for more than 30 minutes','Pain prevents me standing for more than 10 minutes','Pain prevents me from standing at all']],
    ['7. Sleeping',['My sleep is never disturbed by pain','My sleep is occasionally disturbed by pain','Because of pain I have less than 6 hours sleep','Because of pain I have less than 4 hours sleep','Because of pain I have less than 2 hours sleep','Pain prevents me from sleeping at all']],
    ['8. Sex life (if applicable)',['My sex life is normal and causes no extra pain','My sex life is normal but causes some extra pain','My sex life is nearly normal but is very painful','My sex life is severely restricted by pain','My sex life is nearly absent because of pain','Pain prevents any sex life at all']],
    ['9. Social life',['My social life is normal and gives me no extra pain','My social life is normal but increases the degree of pain','Pain has no significant effect apart from limiting energetic interests (e.g. sport)','Pain has restricted my social life and I do not go out as often','Pain has restricted my social life to my home','I have no social life because of pain']],
    ['10. Travelling',['I can travel anywhere without pain','I can travel anywhere but it gives me extra pain','Pain is bad but I manage journeys over two hours','Pain restricts me to journeys of less than one hour','Pain restricts me to short necessary journeys under 30 minutes','Pain prevents me from travelling except to receive treatment']],
  ], showIdx:1,
  score(a){ const x=a.filter(n=>n!==null); if(!x.length) return null; const pct=Math.round(x.reduce((p,c)=>p+c,0)/(x.length*5)*100);
    const band=pct<=20?'Minimal disability':pct<=40?'Moderate disability':pct<=60?'Severe disability':pct<=80?'Crippled':'Bed-bound / exaggerating';
    return {val:pct, txt:`ODI: <b>${pct}%</b> — ${band} <span class="dim">(${x.length}/10 answered; MCID ≈ 10 points)</span>`, lvl:pct>40?'warn':''}; }},
  sb:{t:'Keele STarT Back Screening Tool', short:'STarT Back', items:[
    ['1. My back pain has spread down my leg(s) at some time in the last 2 weeks',['Disagree','Agree']],
    ['2. I have had pain in the shoulder or neck at some time in the last 2 weeks',['Disagree','Agree']],
    ['3. I have only walked short distances because of my back pain',['Disagree','Agree']],
    ['4. In the last 2 weeks, I have dressed more slowly than usual because of back pain',['Disagree','Agree']],
    ['5. It\'s not really safe for a person with a condition like mine to be physically active',['Disagree','Agree']],
    ['6. Worrying thoughts have been going through my mind a lot of the time',['Disagree','Agree']],
    ['7. I feel that my back pain is terrible and it\'s never going to get any better',['Disagree','Agree']],
    ['8. In general I have not enjoyed all the things I used to enjoy',['Disagree','Agree']],
    ['9. Overall, how bothersome has your back pain been in the last 2 weeks?',['Not at all','Slightly','Moderately','Very much','Extremely']],
  ],
  score(a){ if(!a.some(n=>n!==null)) return null; const sc=a.map((x,i)=>i<8?(x===1?1:0):(x>=3?1:0));
    const tot=sc.reduce((p,c)=>p+c,0), ps=sc.slice(4).reduce((p,c)=>p+c,0);
    const risk=tot<=3?'LOW risk':ps<=3?'MEDIUM risk':'HIGH risk';
    const adv=tot<=3?'advice, reassurance, self-management':ps<=3?'physiotherapy-led exercise & manual therapy':'psychologically informed physiotherapy';
    return {val:risk, txt:`STarT Back: total <b>${tot}/9</b>, psychosocial <b>${ps}/5</b> → <b>${risk}</b> (${adv})${a.some(x=>x===null)?' <span class="dim">— incomplete</span>':''}`, lvl:risk==='HIGH risk'?'alert':risk==='MEDIUM risk'?'warn':''}; }},
  ndi:{t:'Neck Disability Index (NDI)', short:'NDI', showIdx:1, items:[
    ['1. Pain intensity',['I have no pain at the moment','The pain is very mild at the moment','The pain is moderate at the moment','The pain is fairly severe at the moment','The pain is very severe at the moment','The pain is the worst imaginable at the moment']],
    ['2. Personal care',['I can look after myself normally without causing extra pain','I can look after myself normally but it causes extra pain','It is painful to look after myself and I am slow and careful','I need some help but manage most of my personal care','I need help every day in most aspects of self-care','I do not get dressed, wash with difficulty and stay in bed']],
    ['3. Lifting',['I can lift heavy weights without extra pain','I can lift heavy weights but it gives extra pain','Pain prevents lifting heavy weights off the floor, but I manage if conveniently positioned','Pain prevents lifting heavy weights, but I manage light–medium weights if conveniently positioned','I can lift very light weights','I cannot lift or carry anything at all']],
    ['4. Reading',['I can read as much as I want with no neck pain','I can read as much as I want with slight neck pain','I can read as much as I want with moderate neck pain','I can\'t read as much as I want because of moderate neck pain','I can hardly read at all because of severe neck pain','I cannot read at all']],
    ['5. Headaches',['I have no headaches at all','I have slight headaches which come infrequently','I have moderate headaches which come infrequently','I have moderate headaches which come frequently','I have severe headaches which come frequently','I have headaches almost all the time']],
    ['6. Concentration',['I can concentrate fully with no difficulty','I can concentrate fully with slight difficulty','I have a fair degree of difficulty concentrating','I have a lot of difficulty concentrating','I have a great deal of difficulty concentrating','I cannot concentrate at all']],
    ['7. Work',['I can do as much work as I want','I can only do my usual work, but no more','I can do most of my usual work, but no more','I cannot do my usual work','I can hardly do any work at all','I can\'t do any work at all']],
    ['8. Driving',['I can drive without any neck pain','I can drive as long as I want with slight neck pain','I can drive as long as I want with moderate neck pain','I can\'t drive as long as I want because of moderate neck pain','I can hardly drive at all because of severe neck pain','I can\'t drive at all']],
    ['9. Sleeping',['I have no trouble sleeping','My sleep is slightly disturbed (< 1 h sleepless)','My sleep is mildly disturbed (1–2 h sleepless)','My sleep is moderately disturbed (2–3 h sleepless)','My sleep is greatly disturbed (3–5 h sleepless)','My sleep is completely disturbed (5–7 h sleepless)']],
    ['10. Recreation',['I can do all my recreational activities with no neck pain','I can do all my recreational activities with some neck pain','I can do most but not all recreational activities because of neck pain','I can do only a few recreational activities because of neck pain','I can hardly do any recreational activities because of neck pain','I can\'t do any recreational activities at all']],
  ],
  score(a){ const x=a.filter(n=>n!==null); if(!x.length) return null; const pct=Math.round(x.reduce((p,c)=>p+c,0)/(x.length*5)*100);
    const band=pct<10?'No disability':pct<30?'Mild disability':pct<50?'Moderate disability':pct<70?'Severe disability':'Complete disability';
    return {val:pct, txt:`NDI: <b>${pct}%</b> (${Math.round(pct/2)}/50) — ${band} <span class="dim">(${x.length}/10 answered; MCID ≈ 7.5 points / 50)</span>`, lvl:pct>=50?'warn':''}; }},
  spadi:{t:'Shoulder Pain and Disability Index (SPADI) — 0 = none, 10 = worst', short:'SPADI', items:[
    ...['At its worst?','When lying on the involved side?','Reaching for something on a high shelf?','Touching the back of your neck?','Pushing with the involved arm?'].map((q,i)=>[`Pain ${i+1}. ${q}`,[...Array(11).keys()].map(String)]),
    ...['Washing your hair?','Washing your back?','Putting on an undershirt or jumper?','Putting on a shirt that buttons down the front?','Putting on your trousers?','Placing an object on a high shelf?','Carrying a heavy object of 10 lb (4.5 kg)?','Removing something from your back pocket?'].map((q,i)=>[`Disability ${i+1}. ${q}`,[...Array(11).keys()].map(String)]),
  ], row:1,
  score(a){ const p=a.slice(0,5).filter(n=>n!==null), d=a.slice(5).filter(n=>n!==null); if(!p.length&&!d.length) return null;
    const pc=p.length?Math.round(p.reduce((x,y)=>x+y,0)/(p.length*10)*100):null, dc=d.length?Math.round(d.reduce((x,y)=>x+y,0)/(d.length*10)*100):null;
    const all=[...p,...d], tot=Math.round(all.reduce((x,y)=>x+y,0)/(all.length*10)*100);
    return {val:tot, txt:`SPADI total: <b>${tot}%</b>${pc!==null?` · Pain <b>${pc}%</b>`:''}${dc!==null?` · Disability <b>${dc}%</b>`:''} <span class="dim">(MCID ≈ 8–13 points)</span>`, lvl:tot>=50?'warn':''}; }},
  qdash:{t:'QuickDASH (arm, shoulder & hand) — past week', short:'QuickDASH', items:[
    ...['Open a tight or new jar','Do heavy household chores (e.g. wash walls, floors)','Carry a shopping bag or briefcase','Wash your back','Use a knife to cut food','Recreational activities in which you take some force or impact through your arm, shoulder or hand (e.g. golf, hammering, tennis)']
      .map((q,i)=>[`${i+1}. ${q}`,['No difficulty','Mild difficulty','Moderate difficulty','Severe difficulty','Unable']]),
    ['7. To what extent has your arm, shoulder or hand problem interfered with normal social activities with family, friends, neighbours or groups?',['Not at all','Slightly','Moderately','Quite a bit','Extremely']],
    ['8. Were you limited in your work or other regular daily activities as a result of your arm, shoulder or hand problem?',['Not limited at all','Slightly limited','Moderately limited','Very limited','Unable']],
    ['9. Arm, shoulder or hand pain',['None','Mild','Moderate','Severe','Extreme']],
    ['10. Tingling (pins and needles) in your arm, shoulder or hand',['None','Mild','Moderate','Severe','Extreme']],
    ['11. Difficulty sleeping because of pain in your arm, shoulder or hand',['No difficulty','Mild difficulty','Moderate difficulty','Severe difficulty','So much I can\'t sleep']],
  ],
  score(a){ const x=a.filter(n=>n!==null); if(!x.length) return null; if(x.length<10) return {val:null, txt:`QuickDASH: ${x.length}/11 answered — <b>at least 10 needed</b> to score`};
    const s=Math.round(((x.reduce((p,c)=>p+c+1,0)/x.length)-1)*25*10)/10;
    return {val:s, txt:`QuickDASH: <b>${s}/100</b> <span class="dim">(0 = no disability; MCID ≈ 15–20 points)</span>`, lvl:s>=40?'warn':''}; }},
  lefs:{t:'Lower Extremity Functional Scale (LEFS) — today, do you have difficulty with…', short:'LEFS', items:
    ['Any of your usual work, housework or school activities','Your usual hobbies, recreational or sporting activities','Getting into or out of the bath','Walking between rooms','Putting on your shoes or socks','Squatting','Lifting an object, like a bag of groceries, from the floor','Performing light activities around your home','Performing heavy activities around your home','Getting into or out of a car','Walking 2 blocks','Walking a mile','Going up or down 10 stairs (about 1 flight)','Standing for 1 hour','Sitting for 1 hour','Running on even ground','Running on uneven ground','Making sharp turns while running fast','Hopping','Rolling over in bed']
    .map((q,i)=>[`${i+1}. ${q}`,['0 Extreme / unable','1 Quite a bit','2 Moderate','3 A little bit','4 No difficulty']]),
  score(a){ const x=a.filter(n=>n!==null); if(!x.length) return null; const s=x.reduce((p,c)=>p+c,0);
    return {val:s, txt:`LEFS: <b>${s}/${x.length*4}</b>${x.length<20?` (${x.length}/20 answered)`:''} — ${Math.round(s/(x.length*4)*100)}% function <span class="dim">(higher = better; MCID ≈ 9 points)</span>`, lvl:s/(x.length*4)<0.5?'warn':''}; }},
  lysholm:{t:'Lysholm Knee Scoring Scale', short:'Lysholm', items:[
    ['Limp (5)',[['None',5],['Slight or periodical',3],['Severe and constant',0]]],
    ['Support (5)',[['None',5],['Cane or crutch',2],['Weight-bearing impossible',0]]],
    ['Locking (15)',[['No locking and no catching sensations',15],['Catching sensation but no locking',10],['Locking occasionally',6],['Locking frequently',2],['Locked joint on examination',0]]],
    ['Instability (25)',[['Never giving way',25],['Rarely during athletic or other severe exertion',20],['Frequently during athletic or severe exertion (or unable to participate)',15],['Occasionally in daily activities',10],['Often in daily activities',5],['Every step',0]]],
    ['Pain (25)',[['None',25],['Inconstant and slight during severe exertion',20],['Marked during severe exertion',15],['Marked on or after walking more than 2 km',10],['Marked on or after walking less than 2 km',5],['Constant',0]]],
    ['Swelling (10)',[['None',10],['On severe exertion',6],['On ordinary exertion',2],['Constant',0]]],
    ['Stair climbing (10)',[['No problems',10],['Slightly impaired',6],['One step at a time',2],['Impossible',0]]],
    ['Squatting (5)',[['No problems',5],['Slightly impaired',4],['Not beyond 90° knee flexion',2],['Impossible',0]]],
  ],
  score(a,items){ if(!a.some(n=>n!==null)) return null; const s=a.reduce((p,c,i)=>p+(c===null?0:items[i][1][c][1]),0); const n=a.filter(x=>x!==null).length;
    const band=s>=95?'Excellent':s>=84?'Good':s>=65?'Fair':'Poor';
    return {val:s, txt:`Lysholm: <b>${s}/100</b> — ${band}${n<8?` <span class="dim">(${n}/8 answered)</span>`:''}`, lvl:s<65?'warn':''}; }},
};

